    /**
     * @Description:重写equals和hashCode方法用contractNumber来去重
     * @Author: Wty
     * @Date: Created om 16:21 2018/6/13
     */
    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (o == null || getClass() != o.getClass()) {
            return false;
        }

        HlsCusFiveClassificationContract that = (HlsCusFiveClassificationContract) o;

        return contractNumber.equals(that.contractNumber);
    }

    @Override
    public int hashCode() {
        return contractNumber.hashCode();
    }

